		contents.add(fieldView, BorderLayout.CENTER);
		contents.add(detailPane, BorderLayout.SOUTH);
		detailPane.add(populationLabel, BorderLayout.CENTER);

		pack();
		setVisible(true);
	}


	public void showStatus(int step, TimeCycle currentTimeCycle, Field field, Climate climate, int infect) {
		if (!isVisible()) {
			setVisible(true);
		}

		stepLabel.setText(STEP_PREFIX + step);
		dayCycleLabel.setText(DAYCYCLE_PREFIX + currentTimeCycle + " ");
		this.climateLabel.setText(CLIMATE_PREFIX + climate.getCurrentSeason());
		this.weatherLabel.setText(WEATHER_PREFIX + climate.getCurrentWeather());
		this.infectLabel.setText(INFECTION_PREFIX + infect + "%");
		this.humidityLabel.setText(HUMIDITY_PREFIX + climate.getHumidity() + "%");
		stats.reset();

		fieldView.preparePaint();


		for (int row = 0; row < field.getDepth(); row++) {
			for (int col = 0; col < field.getWidth(); col++) {
				Animal animal = (Animal) field.getAnimalAt(row, col);
				Object plant = field.getPlantAt(row, col);
				if (animal != null) {
					stats.incrementCount(animal.getClass());
					fieldView.drawMark(col, row, animal.getObjectColor(climate));
				} else if (plant != null) {
					Plant newPlant = (Plant) plant;
					fieldView.drawMark(col, row, newPlant.getObjectColor(climate));
				} else {
					fieldView.drawMark(col, row, EMPTY_COLOR);
				}
			}
		}
		stats.countFinished();

		populationLabel.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
		fieldView.repaint();
	}


	public boolean isViable(Field field) {
		return stats.isViable(field);
	}


	private class FieldView extends JPanel {
		private final int GRID_VIEW_SCALING_FACTOR = 5;
		Dimension size;
		private int gridWidth, gridHeight;
		private int xScale, yScale;
		private Graphics g;
		private Image fieldImage;


		public FieldView(int height, int width) {
			gridHeight = height;
			gridWidth = width;
			size = new Dimension(0, 0);
		}


		public Dimension getPreferredSize() {
			return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
					gridHeight * GRID_VIEW_SCALING_FACTOR);
		}


		public void preparePaint() {
			if (!size.equals(getSize())) {
				size = getSize();
				fieldImage = fieldView.createImage(size.width, size.height);
				g = fieldImage.getGraphics();

				xScale = size.width / gridWidth;
				if (xScale < 1) {
					xScale = GRID_VIEW_SCALING_FACTOR;
				}
				yScale = size.height / gridHeight;
				if (yScale < 1) {
					yScale = GRID_VIEW_SCALING_FACTOR;
				}
			}
		}


		public void drawMark(int x, int y, Color color) {
			g.setColor(color);
			g.fillRect(x * xScale, y * yScale, xScale - 1, yScale - 1);
			g.drawRect(x * xScale, y * yScale, xScale - 1, yScale - 1);
		}


		public void paintComponent(Graphics g) {
			if (fieldImage != null) {
				Dimension currentSize = getSize();
				if (size.equals(currentSize)) {
					g.drawImage(fieldImage, 0, 0, null);
				} else {

					g.drawImage(fieldImage, 0, 0, currentSize.width, currentSize.height, null);
				}
			}
		}
	}
}

import java.util.HashMap;


public class FieldStats {

	private HashMap<Class, Counter> counters;

	private boolean countsValid;


	public FieldStats() {


		counters = new HashMap<>();
		countsValid = true;
	}


	public String getPopulationDetails(Field field) {
		StringBuffer buffer = new StringBuffer();
		if (!countsValid) {
			generateCounts(field);
		}
		for (Class key : counters.keySet()) {
			Counter info = counters.get(key);
			buffer.append(info.getName());
			buffer.append(": ");
			buffer.append(info.getCount());
			buffer.append(' ');
		}
		return buffer.toString();
	}


	public void reset() {
		countsValid = false;
		for (Class key : counters.keySet()) {
			Counter count = counters.get(key);
			count.reset();
		}
	}


	public void incrementCount(Class animalClass) {
		Counter count = counters.get(animalClass);
		if (count == null) {


			count = new Counter(animalClass.getName());
			counters.put(animalClass, count);
		}
		count.increment();
	}


	public void countFinished() {
		countsValid = true;
	}


	public boolean isViable(Field field) {

		int nonZero = 0;
		if (!countsValid) {
			generateCounts(field);
		}
		for (Class key : counters.keySet()) {
			Counter info = counters.get(key);
			if (info.getCount() > 0) {
				nonZero++;
			}
		}
		return nonZero > 1;
	}


	private void generateCounts(Field field) {
		reset();
		for (int row = 0; row < field.getDepth(); row++) {
			for (int col = 0; col < field.getWidth(); col++) {
				Object animal = field.getAnimalAt(row, col);
				if (animal != null) {
					incrementCount(animal.getClass());
				}
			}
		}
		countsValid = true;
	}


	public int getPopulationCount(Field field, Class key) {
		if (!countsValid) {
			generateCounts(field);
		}
		int total = 0;
		for (Class currentKey : counters.keySet()) {
			if (currentKey.equals(key)) {
				Counter counter = counters.get(currentKey);
				total = total + counter.getCount();
			}
		}
		return total;
	}
}

import java.util.Random;


public class Climate {

	private static final int SEASON_LENGTH = 16;

	private static final Random rand = Randomizer.getRandom();

	private Weather currentWeather;

	private Season currentSeason;

	private int humidity;


	public Climate(Weather currentWeather) {
		this.currentWeather = currentWeather;
		currentSeason = Season.SPRING;
	}


	public void updateClimate(int step) {
		updateSeason(step);


		int humidityIncrease = rand.nextInt((20 - 10) + 1) + 10;

		if (humidity < 80 && (currentWeather == Weather.SUN || currentWeather == Weather.CLOUD)) {
			humidity += humidityIncrease;
		} else if (humidity < 100 && (currentWeather == Weather.SUN || currentWeather == Weather.CLOUD)) {
			humidity += humidityIncrease;
			currentWeather = Weather.CLOUD;
		} else if (humidity > 100 && (currentWeather == Weather.SUN || currentWeather == Weather.CLOUD) && currentSeason != Season.WINTER) {
			currentWeather = Weather.RAIN;
		} else if (humidity > 80 && currentWeather == Weather.RAIN) {
			humidity -= humidityIncrease;
		} else {
			humidity = 0;
			currentWeather = Weather.SUN;
		}
	}


	private void updateSeason(int step) {
		switch ((step / SEASON_LENGTH) % 4) {
			case 0:
				currentSeason = Season.SPRING;
				break;
			case 1:
				currentSeason = Season.SUMMER;
				break;
			case 2:
				currentSeason = Season.AUTUMN;
				break;
			case 3:
				currentSeason = Season.WINTER;
				break;
		}
	}


	public Weather getCurrentWeather() {
		return currentWeather;
	}


	public void setCurrentWeather(Weather currentWeather) {
		this.currentWeather = currentWeather;
	}


	public Season getCurrentSeason() {
		return currentSeason;
	}


	public int getHumidity() {
		return humidity;
	}

}

