		frame.pack();
		frame.setLocation(20, 600);

		frame.setVisible(true);

		return frame;
	}


	class GraphPanel extends JComponent {
		private static final double SCALE_FACTOR = 0.8;


		private BufferedImage graphImage;
		private int[] lastVal;
		private int yMax;


		public GraphPanel(int width, int height, int startMax) {
			graphImage = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
			clearImage();
			lastVal = new int[classes.size()];
			Arrays.fill(lastVal, height);
			yMax = startMax;
		}


		public void newRun() {
			int height = graphImage.getHeight();
			int width = graphImage.getWidth();

			Graphics g = graphImage.getGraphics();
			g.copyArea(4, 0, width - 4, height, -4, 0);
			g.setColor(Color.BLACK);
			g.drawLine(width - 4, 0, width - 4, height);
			g.drawLine(width - 2, 0, width - 2, height);
			lastVal = new int[classes.size()];
			Arrays.fill(lastVal, height);
			repaint();
		}


		public void update(int step, Field field, FieldStats stats) {

			Graphics g = graphImage.getGraphics();

			int height = graphImage.getHeight();
			int width = graphImage.getWidth();


			g.copyArea(1, 0, width - 1, height, -1, 0);

			stats.reset();

			int i = 0;
			for (Iterator<Class<?>> it = classes.iterator(); it.hasNext(); i++) {
				Class<?> nextClass = it.next();
				int count = stats.getPopulationCount(field, nextClass);


				int y = height - ((height * count) / yMax) - 1;
				while (y < 0) {
					scaleDown();
					y = height - ((height * count) / yMax) - 1;
				}
				g.setColor(LIGHT_GRAY);
				g.drawLine(width - 2, y, width - 2, height);
				g.setColor(colors.get(nextClass));
				g.drawLine(width - 3, lastVal[i], width - 2, y);
				lastVal[i] = y;
			}

			repaint();

			stepLabel.setText("" + step);
			countLabel.setText(stats.getPopulationDetails(field));

		}


		public void scaleDown() {
			Graphics g = graphImage.getGraphics();
			int height = graphImage.getHeight();
			int width = graphImage.getWidth();

			BufferedImage tmpImage = new BufferedImage(width, (int) (height * SCALE_FACTOR),
					BufferedImage.TYPE_INT_RGB);
			Graphics2D gtmp = (Graphics2D) tmpImage.getGraphics();

			gtmp.scale(1.0, SCALE_FACTOR);
			gtmp.drawImage(graphImage, 0, 0, null);

			int oldTop = (int) (height * (1.0 - SCALE_FACTOR));

			g.setColor(Color.WHITE);
			g.fillRect(0, 0, width, oldTop);
			g.drawImage(tmpImage, 0, oldTop, null);

			yMax = (int) (yMax / SCALE_FACTOR);

			for (int i = 0; i < lastVal.length; i++) {
				lastVal[i] = oldTop + (int) (lastVal[i] * SCALE_FACTOR);
			}

			repaint();
		}


		final public void clearImage() {
			Graphics g = graphImage.getGraphics();
			g.setColor(Color.WHITE);
			g.fillRect(0, 0, graphImage.getWidth(), graphImage.getHeight());
			repaint();
		}


		public Dimension getPreferredSize() {
			return new Dimension(graphImage.getWidth(), graphImage.getHeight());
		}


		public boolean isOpaque() {
			return true;
		}


		public void paintComponent(Graphics g) {
			if (graphImage != null) {
				g.drawImage(graphImage, 0, 0, null);
			}
		}
	}
}

import java.util.Random;


public class Randomizer {

	private static final int SEED = 1111;

	private static final Random rand = new Random(SEED);

	private static final boolean useShared = true;


	public Randomizer() {
	}


	public static Random getRandom() {
		if (useShared) {
			return rand;
		} else {
			return new Random();
		}
	}


	public static void reset() {
		if (useShared) {
			rand.setSeed(SEED);
		}
	}
}

import java.util.Iterator;
import java.util.List;
import java.util.Random;


public abstract class Animal extends Entity {


	private static final Random rand = Randomizer.getRandom();

	private boolean alive;

	private int age;

	private Gender gender = Gender.MALE;

	private boolean nocturnal;

	private int foodChainLevel;

	private int foodValue;

	private int foodLevel;

	private boolean sick;

	private int sickProbability;

	private int recoverProbability;

	private int sickStep;

	private int maxSickStep;


	public Animal(Field field, Location location) {
		super(field, location);
		alive = true;
		gender = gender.randomGender();
		nocturnal = false;
		sick = false;
		sickProbability = 16;
	}


	abstract protected void normalAct(List<Animal> newAnimals);


	public void act(List<Animal> newAnimals, TimeCycle time) {
		incrementAge();
		incrementHunger();
		battleSickness();
		if (isAlive()) {
			if (time == TimeCycle.NIGHT && isNocturnal()) {

				normalAct(newAnimals);
			} else if (time == TimeCycle.DAY && isNocturnal()) {

				normalAct(newAnimals);
			} else if (time == TimeCycle.DAY && !isNocturnal()) {

				normalAct(newAnimals);
			}
		}
	}


	protected void incrementAge() {
		age++;
		if (age > getMaxAge()) {
			setDead();
		}
	}


	private boolean canBreed() {
		Field field = getField();
		List<Location> adjacent = field.adjacentAnimalLocations(getLocation());
		Iterator<Location> it = adjacent.iterator();
		boolean returnValue = age >= getBreedingAge();
		while (it.hasNext()) {
			Location where = it.next();
			Object animal = field.getAnimalAt(where);
			if (animal instanceof Animal) {
				Animal animalNear = (Animal) animal;

				if (animalNear.getClass().equals(this.getClass()) && getGender() != animalNear.getGender()) {
					return returnValue;
				}
			}
		}
		return returnValue;
	}


	private int breed() {
		int births = 0;
		if (canBreed() && rand.nextDouble() <= getBreedingProbability()) {
			births = rand.nextInt(getMaxLitterSize()) + 1;
		}
		return births;
	}


	protected void giveBirth(List<Animal> newAnimals) {


		if (this.getGender() == Gender.FEMALE) {
			Field field = getField();
			List<Location> free = field.getFreeAnimalAdjacentLocations(getLocation());
			int births = breed();
			for (int b = 0; b < births && free.size() > 0; b++) {
				Location loc = free.remove(0);
				Animal young = createNewAnimal(false, field, loc);
				newAnimals.add(young);
			}
		}
	}


	protected boolean isAlive() {
		return alive;
	}


	protected void setDead() {
		alive = false;
		if (getLocation() != null) {
			getField().clear(getLocation());
			setLocationNull();
			setFieldNull();
		}
	}


	protected void becomeSick() {
		if (!isSick()) {
			int randomNumber = rand.nextInt(getSickProbability());
			if (randomNumber == 1) {
				toggleSick();
			}
		}
	}


	protected void notSick() {
		if (isSick()) {
			int randomNumber = rand.nextInt(getRecoverProbability());
			if (randomNumber == 1) {
				toggleSick();
				sickStep = 0;
			}
		}
	}


	protected void battleSickness() {
		if (sick) {
			if (sickStep >= maxSickStep) {
				setDead();
				return;
			}
			sickStep++;
			Field field = getField();
			if (field != null) {
				List<Location> adjacent = field.adjacentAnimalLocations(getLocation());
				Iterator<Location> it = adjacent.iterator();
				while (it.hasNext()) {
					Location where = it.next();
					Object animal = field.getAnimalAt(where);
					if (animal instanceof Animal) {
						Animal nearAnimal = (Animal) animal;
						if (nearAnimal.getClass().equals(this.getClass())) {
							nearAnimal.becomeSick();
						}
					}
				}
				this.notSick();
			}
		} else {
			becomeSick();
		}
	}


	protected void incrementHunger() {
		foodLevel--;
		if (foodLevel <= 0) {
			setDead();
		}
	}


	protected void toggleNocturnal() {
