  5	
  6	public class FieldPopulator {
  7	
  8		private static final double FLOWER_CREATION_PROBABILITY = 0.07;
  9	
 10		private static final double MOUSE_CREATION_PROBABILITY = 0.07;
 11	
 12		private static final double DUCK_CREATION_PROBABILITY = 0.07;
 13	
 14		private static final double BIRD_CREATION_PROBABILITY = 0.07;
 15	
 16		private static final double WOLF_CREATION_PROBABILITY = 0.03;
 17	
 18		private static final double BEAR_CREATION_PROBABILITY = 0.03;
 19	
 20		private final Random random;
 21	
 22		private final GraphView graphView;
 23	
 24		private final Climate climate;
 25	
 26		private final List<AnimalSpawnRule> animalSpawnRules;
 27	
 28	
 29		public FieldPopulator(GraphView graphView, Climate climate) {
 30			this.random = Randomizer.getRandom();
 31			this.graphView = graphView;
 32			this.climate = climate;
 33			this.animalSpawnRules = new ArrayList<>();
 34			registerAnimalSpawnRules();
 35		}
 36	
 37	
 38		public void populate(Field field, List<Animal> animals, List<Plant> plants) {
 39			field.clear();
 40			animals.clear();
 41			plants.clear();
 42	
 43			for (int row = 0; row < field.getDepth(); row++) {
 44				for (int col = 0; col < field.getWidth(); col++) {
 45					Location location = new Location(row, col);
 46					plants.add(createPlant(field, location));
 47	
 48					Animal animal = createAnimal(field, location);
 49					if (animal != null) {
 50						animals.add(animal);
 51						graphView.setColor(animal.getClass(), animal.getObjectColor(climate));
 52					}
 53				}
 54			}
 55		}
 56	
 57	
 58		private Plant createPlant(Field field, Location location) {
 59			if (random.nextDouble() <= FLOWER_CREATION_PROBABILITY) {
 60				return new Flower(field, location);
 61			}
 62			return new Grass(field, location);
 63		}
 64	
 65	
 66		private Animal createAnimal(Field field, Location location) {
 67			for (AnimalSpawnRule rule : animalSpawnRules) {
 68				if (rule.shouldSpawn(random)) {
 69					return rule.createAnimal(field, location);
 70				}
 71			}
 72			return null;
 73		}
 74	
 75	
 76		private void registerAnimalSpawnRules() {
 77			animalSpawnRules.add(new AnimalSpawnRule(BIRD_CREATION_PROBABILITY) {
 78				@Override
 79				Animal createAnimal(Field field, Location location) {
 80					return new Bird(true, field, location);
 81				}
 82			});
 83			animalSpawnRules.add(new AnimalSpawnRule(MOUSE_CREATION_PROBABILITY) {
 84				@Override
 85				Animal createAnimal(Field field, Location location) {
 86					return new Mouse(true, field, location);
 87				}
 88			});
 89			animalSpawnRules.add(new AnimalSpawnRule(DUCK_CREATION_PROBABILITY) {
 90				@Override
 91				Animal createAnimal(Field field, Location location) {
 92					return new Duck(true, field, location);
 93				}
 94			});
 95			animalSpawnRules.add(new AnimalSpawnRule(WOLF_CREATION_PROBABILITY) {
 96				@Override
 97				Animal createAnimal(Field field, Location location) {
 98					return new Wolf(true, field, location);
 99				}
100			});
101			animalSpawnRules.add(new AnimalSpawnRule(BEAR_CREATION_PROBABILITY) {
102				@Override
103				Animal createAnimal(Field field, Location location) {
104					return new Bear(true, field, location);
105				}
106			});
107		}
108	
109	
110		private abstract static class AnimalSpawnRule {
111			private final double spawnProbability;
112	
113	
114			private AnimalSpawnRule(double spawnProbability) {
115				this.spawnProbability = spawnProbability;
116			}
117	
118	
119			private boolean shouldSpawn(Random random) {
120				return random.nextDouble() <= spawnProbability;
121			}
122	
123	
124			abstract Animal createAnimal(Field field, Location location);
125		}
126	}

