 84		public List<Location> getFreeAnimalAdjacentLocations(Location location) {
 85			List<Location> free = new LinkedList<>();
 86			List<Location> adjacent = getAdjacentAnimalLocations(location);
 87			for (Location next : adjacent) {
 88				if (getAnimalAt(next) == null) {
 89					free.add(next);
 90				}
 91			}
 92			return free;
 93		}
 94	
 95	
 96		public Location freeAnimalAdjacentLocation(Location location) {
 97	
 98			List<Location> free = getFreeAnimalAdjacentLocations(location);
 99			if (!free.isEmpty()) {
100				return free.get(0);
101			} else {
102				return null;
103			}
104		}
105	
106	
107		public List<Location> getAdjacentAnimalLocations(Location location) {
108			assert location != null : "Null location passed to getAdjacentAnimalLocations";
109	
110			List<Location> locations = new LinkedList<>();
111			if (location != null) {
112				int row = location.getRow();
113				int col = location.getCol();
114				for (int roffset = -1; roffset <= 1; roffset++) {
115					int nextRow = row + roffset;
116					if (nextRow >= 0 && nextRow < depth) {
117						for (int coffset = -1; coffset <= 1; coffset++) {
118							int nextCol = col + coffset;
119	
120							if (nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
121								locations.add(new Location(nextRow, nextCol));
122							}
123						}
124					}
125				}
126	
127	
128				Collections.shuffle(locations, rand);
129			}
130			return locations;
131		}
132	
133	
134		public int getDepth() {
135			return depth;
136		}
137	
138	
139		public int getWidth() {
140			return width;
141		}
142	}

  1	import java.util.HashMap;
  2	import java.util.Map;
  3	
  4	
  5	public class FieldStats {
  6	
  7		private final Map<Class<?>, Counter> counters;
  8	
  9		private boolean countsValid;
 10	
 11	
 12		public FieldStats() {
 13			counters = new HashMap<>();
 14			countsValid = true;
 15		}
 16	
 17	
 18		public String getPopulationDetails(Field field) {
 19			StringBuilder buffer = new StringBuilder();
 20			if (!countsValid) {
 21				generateCounts(field);
 22			}
 23			for (Class<?> key : counters.keySet()) {
 24				Counter info = counters.get(key);
 25				buffer.append(info.getName());
 26				buffer.append(": ");
 27				buffer.append(info.getCount());
 28				buffer.append(' ');
 29			}
 30			return buffer.toString();
 31		}
 32	
 33	
 34		public void reset() {
 35			countsValid = false;
 36			for (Class<?> key : counters.keySet()) {
 37				Counter count = counters.get(key);
 38				count.reset();
 39			}
 40		}
 41	
 42	
 43		public void incrementCount(Class<?> animalClass) {
 44			Counter count = counters.get(animalClass);
 45			if (count == null) {
 46				count = new Counter(animalClass.getName());
 47				counters.put(animalClass, count);
 48			}
 49			count.increment();
 50		}
 51	
 52	
 53		public void countFinished() {
 54			countsValid = true;
 55		}
 56	
 57	
 58		public boolean isViable(Field field) {
 59	
 60			int nonZero = 0;
 61			if (!countsValid) {
 62				generateCounts(field);
 63			}
 64			for (Class<?> key : counters.keySet()) {
 65				Counter info = counters.get(key);
 66				if (info.getCount() > 0) {
 67					nonZero++;
 68				}
 69			}
 70			return nonZero > 1;
 71		}
 72	
 73	
 74		private void generateCounts(Field field) {
 75			reset();
 76			for (int row = 0; row < field.getDepth(); row++) {
 77				for (int col = 0; col < field.getWidth(); col++) {
 78					Animal animal = field.getAnimalAt(row, col);
 79					if (animal != null) {
 80						incrementCount(animal.getClass());
 81					}
 82				}
 83			}
 84			countsValid = true;
 85		}
 86	
 87	
 88		public int getPopulationCount(Field field, Class<?> key) {
 89			if (!countsValid) {
 90				generateCounts(field);
 91			}
 92			int total = 0;
 93			for (Class<?> currentKey : counters.keySet()) {
 94				if (currentKey.equals(key)) {
 95					Counter counter = counters.get(currentKey);
 96					total = total + counter.getCount();
 97				}
 98			}
 99			return total;
100		}
101	}

