 87				}
 88			}
 89			stats.countFinished();
 90	
 91			populationLabel.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
 92			fieldView.repaint();
 93		}
 94	
 95	
 96		public boolean isViable(Field field) {
 97			return stats.isViable(field);
 98		}
