101		private class FieldView extends JPanel {
102			private final int GRID_VIEW_SCALING_FACTOR = 5;
103			Dimension size;
104			private int gridWidth, gridHeight;
105			private int xScale, yScale;
106			private Graphics g;
107			private Image fieldImage;
108	
109	
110			public FieldView(int height, int width) {
111				gridHeight = height;
112				gridWidth = width;
113				size = new Dimension(0, 0);
114			}
115	
116	
117			public Dimension getPreferredSize() {
118				return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
119						gridHeight * GRID_VIEW_SCALING_FACTOR);
120			}
121	
122	
123			public void preparePaint() {
124				if (!size.equals(getSize())) {
125					size = getSize();
126					fieldImage = fieldView.createImage(size.width, size.height);
127					g = fieldImage.getGraphics();
128	
129					xScale = size.width / gridWidth;
130					if (xScale < 1) {
131						xScale = GRID_VIEW_SCALING_FACTOR;
132					}
133					yScale = size.height / gridHeight;
134					if (yScale < 1) {
135						yScale = GRID_VIEW_SCALING_FACTOR;
136					}
137				}
138			}
139	
140	
141			public void drawMark(int x, int y, Color color) {
142				g.setColor(color);
143				g.fillRect(x * xScale, y * yScale, xScale - 1, yScale - 1);
144				g.drawRect(x * xScale, y * yScale, xScale - 1, yScale - 1);
145			}
146	
147	
148			public void paintComponent(Graphics g) {
149				if (fieldImage != null) {
150					Dimension currentSize = getSize();
151					if (size.equals(currentSize)) {
152						g.drawImage(fieldImage, 0, 0, null);
153					} else {
154	
155						g.drawImage(fieldImage, 0, 0, currentSize.width, currentSize.height, null);
156					}
157				}
158			}
159		}
160	}

